// Block (composition) — an upgrade offer with optional badge, features, and action.
// Card owns the surface, Stack owns arrangement, and Badge/Button own Component labels and behavior.
import { useId, type Ref } from "react";
import { Badge } from "../components/Badge";
import { Button } from "../components/Button";
import { Card } from "../components/Card";
import { Stack } from "../layouts/Stack";
import "./UpgradePrompt.css";

export interface UpgradePromptProps {
  title: string;
  description?: string;
  features?: string[];
  ctaLabel?: string;
  onUpgrade?: () => void;
  badge?: string;
  className?: string;
  ref?: Ref<HTMLDivElement>;
}

export function UpgradePrompt({
  title,
  description,
  features,
  ctaLabel = "Upgrade",
  onUpgrade,
  badge,
  className,
  ref,
}: UpgradePromptProps) {
  const titleId = useId();

  return (
    <Card
      ref={ref}
      role="region"
      aria-labelledby={titleId}
      className={className ? `sd-upgradeprompt ${className}` : "sd-upgradeprompt"}
    >
      <Stack gap="small" className="sd-upgradeprompt__content">
        {/* The name and its supporting line are ONE unit; here the name shares a row with its
            badge, so the group is that ROW plus the description. */}
        <Stack gap="x-small" className="sd-upgradeprompt__heading">
          <Stack direction="row" align="center" gap="x-small" wrap className="sd-upgradeprompt__title-row">
            <>
              <h2 id={titleId} className="sd-upgradeprompt__title sd-type-title-medium">{title}</h2>
            </>
            {badge && <Badge variant="tonal">{badge}</Badge>}
          </Stack>
          {description && (
            <>
              <p className="sd-upgradeprompt__description sd-type-body-medium">{description}</p>
            </>
          )}
        </Stack>
        {/* One rung below the `description` that introduces it — CONTRASTIVE, per
            naming-convention.md § The size axis defaults to `medium`. */}
        {features && features.length > 0 && (
          <ul className="sd-upgradeprompt__features sd-type-body-small">
            {features.map((feature) => <li key={feature}>{feature}</li>)}
          </ul>
        )}
        <Button onPress={onUpgrade}>{ctaLabel}</Button>
      </Stack>
    </Card>
  );
}

.sd-upgradeprompt {
  width: 100%;
}

.sd-upgradeprompt__title,
.sd-upgradeprompt__description,
.sd-upgradeprompt__features {
  margin: 0;
}

.sd-upgradeprompt__features {
  padding-inline-start: var(--sd-space-large);
}

.sd-upgradeprompt__description {
  color: var(--sd-color-text-muted);
}
